create extension if not exists pgcrypto;
create type public.job_status as enum('queued','processing','completed','failed','cancelled');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz default now());
create table public.tools(id text primary key,name text not null,category text not null,enabled boolean not null default true);
insert into public.tools values
('mov-to-mp4','MOV to MP4','video',true),('mp4-to-webm','MP4 to WEBM','video',true),('video-to-mp3','Video to MP3','audio',true),('video-to-gif','Video to GIF','video',true),('wav-to-mp3','WAV to MP3','audio',true),('m4a-to-mp3','M4A to MP3','audio',true),('jpg-to-png','JPG to PNG','image',true),('png-to-jpg','PNG to JPG','image',true),('webp-to-jpg','WEBP to JPG','image',true),('heic-to-jpg','HEIC to JPG','image',true),('jpg-to-pdf','JPG to PDF','document',true),('pdf-to-jpg','PDF to JPG','document',true),('word-to-pdf','Word to PDF','document',true),('background-remover','AI Background Remover','image',true) on conflict do nothing;
create table public.conversion_jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,tool_id text not null references public.tools(id),status public.job_status not null default 'queued',legacy_job_id text,original_filename text not null,output_filename text,input_mime_type text,input_size_bytes bigint,error_message text,created_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,expires_at timestamptz not null default now()+interval '24 hours');
create index conversion_jobs_owner_created on public.conversion_jobs(user_id,created_at desc);
create table public.file_assets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,job_id uuid references public.conversion_jobs(id) on delete cascade,bucket_id text not null check(bucket_id in('source-files','result-files')),object_path text not null,kind text not null,original_filename text not null,mime_type text,size_bytes bigint,created_at timestamptz default now(),expires_at timestamptz default now()+interval '24 hours',unique(bucket_id,object_path));
create table public.batch_jobs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,tool_id text not null references public.tools(id),status public.job_status default 'queued',total_items int default 0,completed_items int default 0,failed_items int default 0,created_at timestamptz default now());
create table public.usage_records(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,tool_id text references public.tools(id),operation text not null,units bigint default 1,bytes_processed bigint default 0,created_at timestamptz default now());
create table public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references auth.users(id) on delete cascade,plan_code text default 'free',status text default 'inactive',created_at timestamptz default now());
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','')) on conflict do nothing;insert into subscriptions(user_id) values(new.id) on conflict do nothing;return new;end $$;
create trigger auth_user_profile after insert on auth.users for each row execute function public.new_profile();
alter table profiles enable row level security;alter table tools enable row level security;alter table conversion_jobs enable row level security;alter table file_assets enable row level security;alter table batch_jobs enable row level security;alter table usage_records enable row level security;alter table subscriptions enable row level security;
create policy profile_read_self on profiles for select to authenticated using(id=auth.uid());
create policy profile_update_self on profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy tools_read_enabled on tools for select to anon,authenticated using(enabled);
create policy jobs_read_self on conversion_jobs for select to authenticated using(user_id=auth.uid());
create policy jobs_insert_self on conversion_jobs for insert to authenticated with check(user_id=auth.uid());
create policy jobs_update_self on conversion_jobs for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy assets_read_self on file_assets for select to authenticated using(user_id=auth.uid());
create policy assets_insert_self on file_assets for insert to authenticated with check(user_id=auth.uid());
create policy assets_delete_self on file_assets for delete to authenticated using(user_id=auth.uid());
create policy batches_read_self on batch_jobs for select to authenticated using(user_id=auth.uid());
create policy batches_insert_self on batch_jobs for insert to authenticated with check(user_id=auth.uid());
create policy usage_read_self on usage_records for select to authenticated using(user_id=auth.uid());
create policy usage_insert_self on usage_records for insert to authenticated with check(user_id=auth.uid());
create policy subscription_read_self on subscriptions for select to authenticated using(user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit) values('source-files','source-files',false,52428800),('result-files','result-files',false,104857600) on conflict(id) do nothing;
create policy source_read_own on storage.objects for select to authenticated using(bucket_id='source-files' and (storage.foldername(name))[1]=auth.uid()::text);
create policy source_insert_own on storage.objects for insert to authenticated with check(bucket_id='source-files' and (storage.foldername(name))[1]=auth.uid()::text);
create policy source_delete_own on storage.objects for delete to authenticated using(bucket_id='source-files' and (storage.foldername(name))[1]=auth.uid()::text);
create policy result_read_own on storage.objects for select to authenticated using(bucket_id='result-files' and (storage.foldername(name))[1]=auth.uid()::text);
create policy result_insert_own on storage.objects for insert to authenticated with check(bucket_id='result-files' and (storage.foldername(name))[1]=auth.uid()::text);
create policy result_delete_own on storage.objects for delete to authenticated using(bucket_id='result-files' and (storage.foldername(name))[1]=auth.uid()::text);
